mepc_setup:       
                  la x10, init
                  csrw 0x341, x10

custom_csr_setup: 
                  csrwi 0x7c0, 1

init_machine_mode:
                  li x10, 0x1800
                  csrw 0x300, x10 # MSTATUS
                  li x10, 0x0
                  csrw 0x304, x10 # MIE
                  li x29, 0x8ffffffc
                  li x10, 0x300
                  slli x10, x10, 8
                  addi x10, x10, 0x3
                  sw x10, 0(x29)
                  csrr x10, 0x300
                  sw x10, 0(x29)
                  li x29, 0x8ffffffc
                  li x10, 0x304
                  slli x10, x10, 8
                  addi x10, x10, 0x3
                  sw x10, 0(x29)
                  csrr x10, 0x304
                  sw x10, 0(x29)
                  mret
init:             
                  li x0, 0x80000000
                  li x1, 0xf2a29fc8
                  li x2, 0x0
                  li x3, 0x0
                  li x4, 0xf55ae986
                  li x5, 0x80000000
                  li x6, 0x6
                  li x7, 0x3
                  li x8, 0xf4f77d4b
                  li x9, 0xb
                  li x10, 0x2e3a97b
                  li x11, 0x2
                  li x13, 0xd3867231
                  li x14, 0x304a526d
                  li x15, 0xa4a7ca8
                  li x16, 0x0
                  li x17, 0x0
                  li x18, 0x80000000
                  li x19, 0x80000000
